using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace RcsMap {
 public static class ContinuousTests {
  static int count;
  static void Check(bool ok,string name){if(!ok)throw new Exception("continuous route: "+name);count++;}
  public static MapDocument Demo(){var d=new MapDocument{Version=4,Terrain=new TerrainMap{BodyHeight=200,ClearanceMargin=20,MaxSlope=20}};d.Settings.Width=10000;d.Settings.Height=5000;d.Settings.Radius=230;d.Settings.PositionTolerance=20;d.Settings.MaxSpeed=500;
   var up=new TerrainSurface{Name="上坡",Kind=SurfaceKind.沿X直坡道,X=1500,Y=1800,Width=1500,Depth=1400,Z1=300,SpeedLimit=200};
   var deck=new TerrainSurface{Name="中间平台",X=3000,Y=1800,Width=2000,Depth=1400,Z0=300,SpeedLimit=130};
   var down=new TerrainSurface{Name="下坡",Kind=SurfaceKind.沿X直坡道,X=5000,Y=1800,Width=1500,Depth=1400,Z0=300,SpeedLimit=180};
   d.Terrain.Surfaces.AddRange(new[]{up,deck,down});string[] ids={TerrainGeometry.Ground,up.Id,deck.Id,down.Id,TerrainGeometry.Ground};for(int i=1;i<ids.Length;i++)d.Terrain.Connections.Add(new SurfaceConnection{A=ids[i-1],B=ids[i]});
   d.Points.Add(new Waypoint(700,2500,0,100));d.Points.Add(new Waypoint(7500,2500,0,100));return d;
  }
  static TerrainLeg Resolve(MapDocument d){TerrainLeg l;string error;Check(TerrainGeometry.TryLeg(d,d.Points[0],d.Points[1],out l,out error),"resolve: "+error);return l;}
  static bool Error(MapDocument d,string word){return d.Validate(false).Any(x=>x.Contains(word));}
  static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
  static object Field(Editor e,string name){return typeof(Editor).GetField(name,Flags).GetValue(e);}
  static object Call(Editor e,string name,params object[] args){return typeof(Editor).GetMethod(name,Flags).Invoke(e,args);}
  static GridItem Find(GridItem item,string name){if(item.PropertyDescriptor!=null&&item.PropertyDescriptor.Name==name)return item;foreach(GridItem child in item.GridItems){var found=Find(child,name);if(found!=null)return found;}return null;}
  static void UI(string folder){string file=Path.Combine(Path.GetFullPath(folder),"continuous-ui.rcsmap.json");File.WriteAllText(file,Demo().Json());
   using(var editor=new Editor()){editor.ShowInTaskbar=false;editor.Opacity=0;editor.Show();Application.DoEvents();editor.OpenRecovery(file);Call(editor,"SelectPoint",1);var grid=(PropertyGrid)Field(editor,"pointProperties");var root=grid.SelectedGridItem;while(root.Parent!=null)root=root.Parent;var travel=Find(root,"Travel");Check(travel!=null,"actual property grid exposes incoming travel mode");travel.PropertyDescriptor.SetValue(grid.SelectedObject,TerrainTravel.保持起点层);typeof(PropertyGrid).GetMethod("OnPropertyValueChanged",Flags).Invoke(grid,new object[]{new PropertyValueChangedEventArgs(travel,TerrainTravel.沿连接表面)});
    Check(((MapDocument)Field(editor,"doc")).Points[1].TerrainTravelMode==1,"real grid event commits mode");Call(editor,"Undo");Check(((MapDocument)Field(editor,"doc")).Points[1].TerrainTravelMode==0,"mode global undo");Check(((PointInspector)((PropertyGrid)Field(editor,"pointProperties")).SelectedObject).Chain.Contains("中间平台"),"undo recomputes inspector chain");Call(editor,"Redo");Check(((MapDocument)Field(editor,"doc")).Points[1].TerrainTravelMode==1,"mode global redo");Call(editor,"Undo");var tabs=(TabControl)Field(editor,"viewTabs");foreach(int view in new[]{1,2,0}){tabs.SelectedIndex=view;Application.DoEvents();}Check(((MapDocument)Field(editor,"doc")).Points.Count==2,"view changes do not insert seam task points");typeof(Editor).GetField("savedJson",Flags).SetValue(editor,((MapDocument)Field(editor,"doc")).Json());editor.Close();}
  }
  public static void Run(string folder){Directory.CreateDirectory(folder);var d=Demo();string json=d.Json();var l=Resolve(d);Check(d.Validate().Count==0,"two endpoint map valid: "+String.Join(" / ",d.Validate().ToArray()));Check(l.Spans.Count==5,"ground uphill deck downhill ground");Check(d.Points.Count==2,"no implicit task points");Check(d.Json()==json,"search never mutates document");Check(l.SpeedLimit==130,"intermediate minimum speed");Check(l.MaxSlope>11&&l.MaxSlope<12,"intermediate maximum slope");Check(Math.Abs(l.Length-(800+2*Math.Sqrt(1500*1500+300*300)+2000+1000))<1e-6,"piecewise 3D arc length");Check(TerrainGeometry.Vertices(d.Points[0],d.Points[1],l).Max(v=>v[3])==300,"profile includes hidden peak");Check(l.Z0==0&&l.Z1==0&&TerrainGeometry.HasRelief(d),"same ground endpoints cannot bypass relief guard");bool blocked=false;try{Exporter.Generate(d);}catch(InvalidOperationException){blocked=true;}Check(blocked,"nonflat firmware export blocked");Check(d.Points.All(p=>p.ArrivalActions.Count==0&&p.DepartureActions.Count==0),"seams have no actions");Check(MapDocument.Parse(json).Json()==json,"roundtrip");
   var c=d.Clone();c.Points.Reverse();var reverse=Resolve(c);Check(c.Validate().Count==0,"reverse route");Check(Math.Abs(l.Length-reverse.Length)<1e-6,"reverse distance");Check(reverse.Spans[1].Angle>0&&reverse.Spans[3].Angle<0,"reverse ramp slopes");
   c=d.Clone();c.Terrain.Connections.RemoveAt(1);Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json),"missing middle link never falls back to ground");Check(Error(c,"未声明"),"missing link explanation");c=d.Clone();c.Terrain.Surfaces[1].X+=10;Check(Error(c,"接合边"),"physical gap rejected");c=d.Clone();c.Terrain.Surfaces[1].Z0+=10;Check(Error(c,"接合边"),"height step rejected");c=d.Clone();c.Points[1].Speed=150;Check(Error(c,"限速"),"intermediate deck speed enforced");c=d.Clone();c.Terrain.MaxSlope=5;Check(Error(c,"坡度"),"intermediate slope enforced");c=d.Clone();c.Terrain.Surfaces[1].Depth=300;Check(Error(c,"窄于"),"narrow middle deck");c=d.Clone();c.Points[0].Y=c.Points[1].Y=1830;Check(Error(c,"车体包络"),"ramp lateral body clearance");
   c=d.Clone();c.Obstacles.Add(new Obstacle(3600,2300,400,400){SurfaceId=c.Terrain.Surfaces[1].Id});Check(Error(c,"障碍物安全包络"),"middle deck obstacle");Check(TerrainGeometry.ObstacleHits(c,c.Points[0],c.Points[1],c.Obstacles[0]),"obstacle uses all spans");c.Obstacles[0].SurfaceId=null;Check(!TerrainGeometry.ObstacleHits(c,c.Points[0],c.Points[1],c.Obstacles[0]),"lower obstacle does not block upper deck");
   c=d.Clone();c.Terrain.Surfaces.Add(new TerrainSurface{Name="额外天花板",X=3500,Y=1800,Width=1000,Depth=1400,Z0=450,Thickness=50,SpeedLimit=200});Check(Error(c,"净空不足"),"intermediate overhead deck");c.Terrain.Surfaces.Last().Z0=900;Check(!Error(c,"净空不足"),"adequate middle clearance");
   c=d.Clone();c.Points[1].X=4500;c.Points[1].SurfaceId=c.Terrain.Surfaces[1].Id;Check(c.Validate().Count==0,"ground ramp deck needs only endpoints");Check(Resolve(c).Spans.Count==3,"three surface chain");c.Points[0].Y=600;c.Points[1].Y=2000;Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json),"graph path alone cannot detour a straight leg");
   c=d.Clone();c.Points[1].TerrainTravelMode=1;Check(Resolve(c).Spans.Count==1,"explicit stay layer");Check(Error(c,"净空不足"),"stay layer cannot bypass low ramp collision");c=d.Clone();c.Points[0].X=4000;c.Points[0].Y=700;c.Points[1].X=4000;c.Points[1].Y=4200;c.Terrain.BodyHeight=100;Check(c.Validate().Count==0,"bridge underpass without ramp entrance");Check(!TerrainGeometry.HasRelief(c)&&Resolve(c).Spans.Count==1,"bridge underpass remains flat");c.Points[1].TerrainTravelMode=1;Check(c.Clone().Points[1].TerrainTravelMode==1,"explicit mode serialized");Check(new PointInspector(c,1).Travel==TerrainTravel.保持起点层,"mode exposed in inspector");new PointInspector(c,1).Travel=TerrainTravel.沿连接表面;Check(c.Points[1].TerrainTravelMode==0,"inspector setter");Check(new PointInspector(d,1).Chain.Contains("中间平台"),"inspector shows full chain");
   c=d.Clone();var other=Demo();foreach(var s in other.Terrain.Surfaces){s.Z0*=2;s.Z1*=2;}c.Terrain.Surfaces.AddRange(other.Terrain.Surfaces);c.Terrain.Connections.AddRange(other.Terrain.Connections);Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json)&&json.Contains("歧义"),"multiple valid surface chains rejected");c.Terrain.Surfaces.Reverse();c.Terrain.Connections.Reverse();Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json)&&json.Contains("歧义"),"ambiguity independent of list order");
   c=d.Clone();c.Points[1].X=c.Points[0].X;c.Points[1].Y=c.Points[0].Y;Check(Resolve(c).Length==0,"same layer stationary");c=d.Clone();c.Points[1].TerrainTravelMode=99;Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json),"invalid mode rejected");var flat=MapDocument.Demo();Check(!flat.Json().Contains("TerrainTravelMode"),"legacy default JSON unchanged");Check(Exporter.Generate(flat).Count==6,"legacy six files retained");
   c=d.Clone();foreach(var face in c.Terrain.Surfaces){face.Kind=SurfaceKind.水平平台;face.Z0=face.Z1=0;}Check(c.Validate().Count==0,"zero height connected platforms valid");Check(!TerrainGeometry.HasRelief(c)&&Exporter.Generate(c).Count==6,"flattened route permits flat export");Check(!TerrainGeometry.HasRelief(c.Clone()),"no persisted stale relief flag");
   c=d.Clone();c.Points[1].X=3000;c.Points[1].SurfaceId=c.Terrain.Surfaces[1].Id;l=Resolve(c);Check(l.Spans.Last().Surface.Id==c.Points[1].SurfaceId&&Math.Abs(l.Z1-300)<1e-6,"endpoint exactly on shared edge respects layer");c=d.Clone();c.Points[0].X=c.Points[1].X=4000;c.Points[1].SurfaceId=c.Terrain.Surfaces[1].Id;Check(!TerrainGeometry.TryLeg(c,c.Points[0],c.Points[1],out l,out json),"stationary XY cannot teleport layers");
   c=d.Clone();c.Terrain.Surfaces.Reverse();c.Terrain.Connections.Reverse();Check(Math.Abs(Resolve(c).Length-Resolve(d).Length)<1e-6,"unique chain independent of input ordering");Check(!d.Json().Contains("Spans")&&!d.Json().Contains("Handoff"),"derived geometry absent from saved map");UI(folder);
   File.WriteAllText(Path.Combine(folder,"continuous-selftest.txt"),"PASS "+count+" continuous-surface checks\n");Console.WriteLine("PASS "+count+" continuous-surface checks");
  }
 }
}
